477	function parseThresholds(thresholdSpecs: string[] | undefined, validMetricIds: string[]): Record<string, number> {
478	  if (!thresholdSpecs || thresholdSpecs.length === 0) {
479	    return {};
480	  }
481	
482	  const thresholds: Record<string, number> = {};
483	  const validIds = new Set(validMetricIds);
484	
485	  for (const spec of thresholdSpecs) {
486	    const match = spec.match(/^([a-z_]+)=([0-9.]+)$/);
487	    if (!match) {
488	      log.error(`Invalid threshold format: "${spec}". Expected format: metric=min (e.g., exact_match=0.9)`);
489	      process.exit(2);
490	    }
491	
492	    const [, metricId, minStr] = match;
493	    const min = Number(minStr);
494	
495	    if (Number.isNaN(min) || min < 0 || min > 1) {
496	      log.error(`Invalid threshold value: ${min}. Minimum must be a number between 0 and 1.`);
497	      process.exit(2);
498	    }
499	
500	    if (!validIds.has(metricId)) {
501	      log.error(`Unknown metric id: "${metricId}". Valid metric ids are: ${validMetricIds.join(', ')}`);
502	      process.exit(2);
503	    }
504	
505	    thresholds[metricId] = min;
506	  }
507	
508	  return thresholds;
509	}
