520	  });
521	
522	  const validMetricIds = evaluations.map((m: any) => m.id);
523	  const thresholds = parseThresholds(options.threshold, validMetricIds);
524	
525	  const report = (Eval.generateReport as unknown as (config: unknown) => any)({
526	    evaluations,
527	    outputsPath: dataset.outputsPath,
528	    referencesPath: dataset.referencesPath,
529	    thresholds
530	  });
531	  const resolvedPath = (Eval.writeReport as unknown as (config: unknown) => string)({
532	    report,
533	    format: options.format ?? 'json',
534	    reportPath: options.report
535	  });
536	  log.success('Evaluation report generated.', { path: resolvedPath });
537	
538	  if (Object.keys(thresholds).length > 0 && !report.passed) {
539	    process.exit(1);
540	  }
541	}
